      kind: "value",
      path: requirePath(tag, position),
      escaped: true,
      position,
    });
  }

  if (stack.length > 1) {
    const open = stack[stack.length - 1]!.block!;
    throw new TemplateError(`Unclosed ${JSON.stringify(open.kind)} block`, open.position);
  }

