    if (node.kind === "value") {
      const text = scalarText(value, node.path, node.position);
      output += node.escaped ? escapeHtml(text) : text;
    } else if (node.kind === "if") {
      output += renderNodes(isTruthy(value) ? node.truthy : node.falsy, root, scopes);
